export function isAllowedTool(toolName: string, allowedTools?: string[]): boolean {
  return !allowedTools || allowedTools.includes(toolName);
}

export function formatPromptValue(value: unknown): string {
  if (value === null) {
    return 'null';
  }
  if (Array.isArray(value)) {
    return `[${value.map(formatPromptValue).join(',')}]`;
  }
  if (typeof value === 'object') {
    const record = value as Record<string, unknown>;
    return `{${Object.keys(record)
      .sort()
      .map((key) => `${key}:${formatPromptValue(record[key])}`)
      .join(',')}}`;
  }
  if (typeof value === 'string') {
    return `"${value.replaceAll('\\', '\\\\').replaceAll('"', '\\"')}"`;
  }
  if (typeof value === 'number' || typeof value === 'boolean' || typeof value === 'bigint') {
    return String(value);
  }
  if (typeof value === 'undefined') {
    return 'undefined';
  }
  return Object.prototype.toString.call(value);
}

export function parseToolArgs(rawArgs: string | undefined): Record<string, unknown> {
  if (!rawArgs) {
    return {};
  }
  try {
    return JSON.parse(rawArgs);
  } catch {
    return {};
  }
}

import { StructuredLogger } from '../logging/structured-logger';
import type { AbiBuilderService } from './abi/abi-builder.service';
import { validateAbiPayload } from './abi/abi-validator';

export async function buildUnifiedAgentCognitiveState(
  abiBuilder: AbiBuilderService | undefined,
  currentInput: { raw: string; channel: string; arrivalTimestamp: string },
  logger: StructuredLogger,
): Promise<Record<string, unknown>> {
  let cognitiveState: Record<string, unknown> = {
    abiStatus: abiBuilder ? 'unavailable_or_invalid' : 'builder_not_injected',
    audience: 'public',
    perceptionSnapshot: { channel: currentInput.channel },
  };

  if (abiBuilder) {
    const abiResult = await abiBuilder.build({
      audience: 'public',
      currentInput,
      perceptionSnapshot: {
        channel: currentInput.channel,
      },
    });

    if (abiResult.status !== 'ok') {
      logger.warn(
        `ABI build failed: ${abiResult.reason}, using structured unified agent fallback`,
      );
    } else {
      const abi = abiResult.abi;
      const validation = validateAbiPayload(abi);

      if (validation.status === 'FAIL') {
        logger.warn(
          `ABI validation failed: ${JSON.stringify(validation.issues)}, using structured unified agent fallback`,
        );
      } else {
        cognitiveState = abi as unknown as Record<string, unknown>;
      }
    }
  }

  return cognitiveState;
}

import type { AgentRuntimeContextService } from './agent-runtime';

export async function buildAgentRuntimeContext(
  agentRuntime: AgentRuntimeContextService | undefined,
  params: {
    workspaceId: string;
    channel: string;
    message: string;
    contactId?: string;
    allowedTools?: string[];
  },
): Promise<{ systemPromptBlock: string }> {
  if (!agentRuntime) {
    return { systemPromptBlock: '' };
  }
  return agentRuntime.buildContext(params);
}

